entries[93441] = { ["name"] = "Necklace with Elune Pendant", ["text"] = "3 sec cast 5\nElune is the primary goddess of the night elves. She is associated with the larger of the two moons, the White Lady. While she is a goddess of peace, she is not a pacifist. One of her aspects is the Night Warrior, who takes the valiant among the dead and sets them riding across the sky as stars.\nNecklace with Elune Pendant\nBinds when picked up" }
entries[93442] = { ["name"] = "Shard of Petrified Wood", ["text"] = "3 sec cast 5\nWhile no actual tissue remains, the vascular structure of the wood is preserved perfectly. The plant was most likely a palm or cycad of some kind.\nShard of Petrified Wood\nBinds when picked up" }
entries[93443] = { ["name"] = "Strange Velvet Worm", ["text"] = "3 sec cast 5\nThis fossil appears to be a missing link of some kind. It shares properties of both arthropods and worms. Its body is worm-like, but it has stubby legs like an insect or crustacean. It appears to have been covered with fine velvet-like hair.\nStrange Velvet Worm\nBinds when picked up" }
